const token=location.hash.slice(1);history.replaceState(null,'',location.pathname);const b=document.querySelector('#verify-email');b.disabled=!token;b.onclick=async()=>{b.disabled=true;try{const r=await fetch('/api/email-verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})});const d=await r.json();document.querySelector('#verify-status').textContent=d.message||d.error}catch{document.querySelector('#verify-status').textContent='Verifica non disponibile. Riprova.';b.disabled=false}};